// ---- Üyelikler ----

// UyeRow üyelik tablosu satırı.
type UyeRow struct {
	ID         int64
	Name       string
	Email      string
	Role       string
	Membership string
	Premium    bool
	// Katman (abonelik) bilgileri.
	TierName  string
	TierColor string
	Until     string
	Cycle     string
}

// UyeTier katman düzenleme satırı.
type UyeTier struct {
	ID          int64
	Slug        string
	Name        string
	Description string
	ColorHex    string
	Weight      int
	Monthly     string
	Annual      string
	Perks       string
	Active      bool
}

// UyePayment ödeme panosu satırı.
type UyePayment struct {
	ID       int64
	UserName string
	TierName string
	Provider string
	Status   string
	Amount   string
	Cycle    string
	Created  string
}

// UyeTierCount kademe dağılımı.
type UyeTierCount struct {
	Name  string
	Count int
}

// UyePromo indirim kodu satırı.
type UyePromo struct {
	ID       int64
	Code     string
	Percent  int
	TierSlug string
	Uses     string
	Expires  string
	Active   bool
}

// UyeTrend aylık gelir grafiği çubuğu.
type UyeTrend struct {
	Short  string
	Label  string
	Amount string
	Count  int
	Pct    int // 0..100 (en yüksek aya göre)
}

// UyelerView üyelikler paneli.
type UyelerView struct {
	FlashKind string
	FlashText string
	// Ara üye listesindeki metin araması (Faz 168, N-11).
	Ara   string
	Items []UyeRow
	// Stripe ödeme ayarları (settings section='stripe').
	StripeSecret     string
	StripeSecretSet  bool
	StripeWebhook    string
	StripeWebhookSet bool
	StripePrice      string
	StripeAktif      bool
	// Google ile giriş (settings section='google').
	GoogleClientID     string
	GoogleClientSecret string
	GoogleSecretSet    bool
	// Üye kaydı anahtarı (settings section='uyelik', key='kayit_acik').
	KayitAcik bool
	// iyzico (settings section='iyzico').
	IyzicoKey       string
	IyzicoSecretSet bool
	IyzicoMode      string
	IyzicoAktif     bool
	// Katmanlar + ödeme panosu.
	Tiers      []UyeTier
	TierEdit   *UyeTier
	Payments   []UyePayment
	StatActive int
	StatRev30  string
	StatRevY   string
	StatFailed int
	TierCounts []UyeTierCount
	// Ekonomi (Faz 5): MRR/ARR/churn/LTV + kuponlar.
	EconMRR     string
	EconARR     string
	EconARPU    string
	EconChurn   string
	EconLTV     string
	EconRenewal string
	EconRefund  string
	EconNew     int
	EconCancel  int
	Promos      []UyePromo
	// Aylık gelir trendi (son 12 ay).
	Trend        []UyeTrend
	TrendHasData bool
}

